#!/usr/bin/env python3
import re

METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
PERMS = {"ALLOW", "DENY"}
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def norm_path(p):
    return VAR_RE.sub("{var}", p)


def read_blocks(text):
    blocks, cur = [], []
    for line in text.splitlines():
        if line.strip() == "":
            if cur:
                blocks.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        blocks.append(cur)
    return blocks


def main():
    with open("/app/input.txt") as f:
        text = f.read()
    blocks = read_blocks(text)
    ep_lines = blocks[0] if len(blocks) > 0 else []
    be_lines = blocks[1] if len(blocks) > 1 else []
    plan_lines = blocks[2] if len(blocks) > 2 else []

    # ---- ENDPOINTS (hard cutoff on malformed) ----
    endpoints = []
    for line in ep_lines:
        f = line.split()
        if len(f) != 4:
            break
        path, method, role, perm = f
        method = method.upper()
        perm = perm.upper()
        if path.strip() == "" or role.strip() == "" or method not in METHODS or perm not in PERMS:
            break
        endpoints.append({"path": path, "norm": norm_path(path),
                          "method": method, "role": role, "perm": perm})

    # ---- BASE/EXCLUDE ----
    base = None
    excluded = set()
    for line in be_lines:
        f = line.split()
        if not f:
            continue
        if f[0] == "base" and len(f) >= 2:
            base = f[1]
        elif f[0] == "exclude":
            excluded.update(f[1:])

    # ---- PLAN (hard cutoff on malformed) ----
    plan = []
    for line in plan_lines:
        f = line.split()
        if len(f) != 2:
            break
        path, method = f
        method = method.upper()
        if path.strip() == "" or method not in METHODS:
            break
        plan.append((norm_path(path), method))

    def base_ok(ep):
        return base is None or ep["path"].startswith(base)

    def eligible(ep):
        return base_ok(ep) and ep["role"] not in excluded

    ep_keys = {(ep["norm"], ep["method"]) for ep in endpoints}
    all_norms = {ep["norm"] for ep in endpoints}

    selected = []
    if not plan:
        selected = [ep for ep in endpoints if eligible(ep)]
    else:
        # eligible endpoints that are in PLAN
        plan_set = set(plan)
        selected = [ep for ep in endpoints if eligible(ep) and (ep["norm"], ep["method"]) in plan_set]
        # parent path resolution
        parent_norms = set()
        for (n, m) in plan:
            if (n, m) not in ep_keys:
                continue
            for p in all_norms:
                if p != n and n.startswith(p):
                    parent_norms.add(p)
        for p in parent_norms:
            eps = [ep for ep in endpoints if ep["norm"] == p]
            elig = [ep for ep in eps if eligible(ep)]
            if elig:
                selected.extend(elig)
            else:
                # special case: parent path whose only endpoints are for excluded roles
                base_only = [ep for ep in eps if base_ok(ep)]
                if base_only:
                    selected.extend(base_only)

    # ---- dedup by (norm path, method, role), first encountered wins ----
    seen = {}
    for ep in selected:
        key = (ep["norm"], ep["method"], ep["role"])
        if key not in seen:
            seen[key] = ep

    # first original path per normalized path (input order)
    first_path = {}
    for ep in endpoints:
        if ep["norm"] not in first_path:
            first_path[ep["norm"]] = ep["path"]

    items = list(seen.values())

    def seg_count(p):
        return len([s for s in p.split("/") if s])

    items.sort(key=lambda ep: (-seg_count(ep["norm"]), ep["method"], ep["role"],
                               0 if ep["perm"] == "ALLOW" else 1))

    lines = ["{} {} {} {}".format(first_path[ep["norm"]], ep["method"], ep["role"], ep["perm"])
             for ep in items]
    with open("/app/output.txt", "w") as f:
        if lines:
            f.write("\n".join(lines) + "\n")
        else:
            f.write("\n")


if __name__ == "__main__":
    main()
